"""Direct-touch five-in-a-row widget for Telegram's restricted renderer."""

import zlib

HTML = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>
*{box-sizing:border-box}body{margin:0;background:transparent;color:#e9f6f3;font:13px system-ui,sans-serif}
.shell{width:100%;padding:12px;border:1px solid #3f7280;border-radius:18px;background:linear-gradient(150deg,#173642,#0c2430)}
.top,.heading,.players,.foot{display:flex;align-items:center;justify-content:space-between}
.top{height:22px}.brand{font-size:10px;font-weight:800;letter-spacing:1px;color:#a3d9d9}.tag{font-size:10px;font-weight:800;padding:4px 8px;border-radius:12px;background:#2d6470;color:#fff}
.heading{height:38px}.heading h1{margin:0;font-size:20px}.clock{min-width:60px;text-align:center;font-size:12px;font-weight:800;color:#ffe0a0}
.players{height:32px;gap:8px}.player{display:flex;align-items:center;gap:5px;font-size:11px;font-weight:750}.token{display:inline-grid;place-items:center;width:21px;height:21px;border-radius:50%;font-weight:900}.token.x{background:#70ded0;color:#113d43}.token.o{background:#ffb09b;color:#603639}.mid{font-size:10px;color:#9cb9bc}
.status{height:34px;line-height:24px;padding:5px 7px;border-radius:9px;background:#245669;color:#fff;font-size:11px;font-weight:800;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.board-frame{margin-top:8px;padding:5px;border:1px solid #5d8b94;border-radius:12px;background:#163944}
.board{width:282px;height:282px;margin:0 auto;direction:ltr;border:1px solid #6c9aa1;border-radius:6px;overflow:hidden}
.row{display:flex;width:100%;height:28px}
.cell{display:flex;align-items:center;justify-content:center;flex-shrink:0;width:28px;height:28px;min-width:28px;min-height:28px;margin:0;padding:0;border:1px solid #537e87;border-radius:0;background:#1a4350;color:#fff;cursor:pointer}
.cell:disabled{cursor:default;opacity:1}.cell:not(:disabled):active{background:#3c7a83}.cell.last{background:#2a6873}.cell.win{background:#3d8178}
.piece{display:flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;font-size:15px;font-weight:900;line-height:1}
.piece.empty{width:3px;height:3px;background:#7daeb6}.piece.x{background:#71e1d0;color:#104049}.piece.o{background:#ffb6a0;color:#613b3e}.piece.ghost{background:#4baca4}
.board.legacy{width:272px;height:272px}.legacy .row,.legacy .cell{height:18px;min-height:18px}.legacy .cell{width:18px;min-width:18px}.legacy .piece{width:14px;height:14px;font-size:11px}.legacy .piece.empty{width:2px;height:2px}
@media(max-width:319px){.board{width:242px;height:242px}.row,.cell{height:24px;min-height:24px}.cell{width:24px;min-width:24px}.piece{width:17px;height:17px;font-size:13px}}
@media(max-width:279px){.board{width:202px;height:202px}.row,.cell{height:20px;min-height:20px}.cell{width:20px;min-width:20px}.piece{width:15px;height:15px;font-size:11px}}
@media(max-width:239px){.board{width:162px;height:162px}.row,.cell{height:16px;min-height:16px}.cell{width:16px;min-width:16px}.piece{width:12px;height:12px;font-size:9px}}
@media(min-width:380px){.board{width:342px;height:342px}.row,.cell{height:34px;min-height:34px}.cell{width:34px;min-width:34px}.piece{width:24px;height:24px;font-size:17px}}
.foot{height:24px;gap:8px;font-size:10px;color:#b5d0d1}.mode{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.rule{white-space:nowrap}
</style></head><body><main class="shell"><div class="top"><span class="brand">GOD OF DARS · GAME</span><span class="tag">دوز پیشرفته</span></div><div class="heading"><h1>پنج‌تایی</h1><span class="clock" id="clock"></span></div><div class="players"><span class="player"><span class="token x">X</span><span id="xname">تو</span></span><span class="mid">VS</span><span class="player"><span id="oname">حریف</span><span class="token o">O</span></span></div><div class="status" id="status">در حال بارگذاری…</div><div class="board-frame"><div class="board" id="board"></div></div><div class="foot"><span class="mode" id="mode">بازی با ربات</span><span class="rule" id="rule">۱۰×۱۰ · پنج مهره = برد</span></div></main><script>
var state={},busy=false,preview=-1,cells=[],size=10,winning={};
function read(raw){try{return JSON.parse(raw||'{}')}catch(e){return {}}}
function me(){return TelegramWidget.viewer&&TelegramWidget.viewer.id}
function winCells(board){var found={};for(var r=0;r<size;r++)for(var c=0;c<size;c++){var mark=board[r*size+c];if(mark==='.')continue;var dirs=[[0,1],[1,0],[1,1],[1,-1]];for(var d=0;d<4;d++){var dr=dirs[d][0],dc=dirs[d][1];if(r+4*dr<0||r+4*dr>=size||c+4*dc<0||c+4*dc>=size)continue;var ok=true;for(var n=1;n<5;n++)if(board[(r+n*dr)*size+c+n*dc]!==mark)ok=false;if(ok)for(var k=0;k<5;k++)found[(r+k*dr)*size+c+k*dc]=true}}return found}
function tick(){document.getElementById('clock').textContent=state.status==='active'?Math.max(0,Math.ceil((state.deadline*1000-Date.now())/1000))+' ثانیه':'پایان بازی'}
function render(){var mine=state.turn===me(),active=state.status==='active',board=state.board||'',myMark=state.challenger===me()?'X':'O';winning=state.status==='finished'?winCells(board):{};for(var i=0;i<cells.length;i++){var cell=cells[i],mark=board[i]||'.',ghost=false;if(mark==='.'&&preview===i){mark=myMark;ghost=true}cell.className='cell'+(i===state.last_move?' last':'')+(winning[i]?' win':'');cell.disabled=!active||!mine||busy||mark!=='.';var piece=cell.firstChild;piece.className='piece '+(mark==='.'?'empty':mark.toLowerCase())+(ghost?' ghost':'');piece.textContent=mark==='.'?'':mark}document.getElementById('xname').textContent=state.challenger===me()?'تو':'حریف';document.getElementById('oname').textContent=state.challenger===me()?(state.mode==='computer'?'ربات':'حریف'):'تو';document.getElementById('status').textContent=busy?'در حال ثبت حرکت…':active?(mine?'نوبت توئه · روی یک خانه بزن':'نوبت حریفه'):state.status==='cancelled'?'بازی لغو شد':state.winner===null?'بازی مساوی شد':state.winner===me()?'برنده شدی! 🎉':'بازی را باختی';document.getElementById('mode').textContent=state.mode==='wager'?'شرط '+state.stake+' '+(state.currency==='coin'?'طلا':'الماس'):state.mode==='computer'?'بازی با ربات':'بازی دوستانه';tick()}
function build(){var board=document.getElementById('board');size=state.board&&state.board.length===225?15:10;if(size===15)board.className='board legacy';document.getElementById('rule').textContent=(size===10?'۱۰×۱۰':'۱۵×۱۵')+' · پنج مهره = برد';for(var r=0;r<size;r++){var row=document.createElement('div');row.className='row';for(var c=0;c<size;c++){var cell=document.createElement('button'),piece=document.createElement('span'),i=r*size+c;cell.type='button';cell.className='cell';cell.dataset.i=String(i);piece.className='piece empty';cell.appendChild(piece);row.appendChild(cell);cells.push(cell)}board.appendChild(row)}}
document.getElementById('board').addEventListener('click',function(e){var cell=e.target.closest('button');if(!cell||cell.disabled||busy)return;var index=Number(cell.dataset.i);preview=index;busy=true;render();TelegramWidget.request('move:'+state.id+':'+index).then(function(answer){var next=read(answer.result);busy=false;preview=-1;if(next.board){state=next;render()}else{render();if(next.error)document.getElementById('status').textContent=next.error}},function(){busy=false;preview=-1;render();document.getElementById('status').textContent='ارتباط برقرار نشد؛ دوباره بزن'})});
state=read(TelegramWidget.chatData||TelegramWidget.publicData);build();TelegramWidget.onEvent('chatDataChanged',function(){var next=read(TelegramWidget.chatData);if(next.board){state=next;render()}});if(typeof TelegramWidget.setResizeAnchor==='function')TelegramWidget.setResizeAnchor('top');render();TelegramWidget.ready();setInterval(tick,1000);
</script></body></html>"""

assert len(HTML.encode()) <= 32768 and len(zlib.compress(HTML.encode(), 9)) <= 4096
